import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let real numbers x and y be defined by\nx = (({a}-1)({b}-1)) / ( [prod_{k=1..{n}} ({a}^(1/2^k)+1)] [prod_{k=1..{m}} ({b}^(1/2^k)+1)] ),\ny = ({a}-1)/[prod_{k=1..{n}} ({a}^(1/2^k)+1)] + ({b}-1)/[prod_{k=1..{m}} ({b}^(1/2^k)+1)].\nCompute (x + y + 1)^{ {power} }.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Generate integers a,b > 1 and depths n,m >= 2 such that n != m to avoid triviality.
# Use modest sizes so the final integer is not enormous but nontrivial.
while True:
    a = rng.randint(2, 12)
    b = rng.randint(2, 12)
    # Avoid a=b occasionally to add variety
    if a == b and rng.random() < 0.5:
        continue
    n = rng.randint(2, 5)
    m = rng.randint(2, 5)
    if n == m:
        continue  # enforce different depths for added difficulty
    maxnm = max(n, m)
    power = 2 ** maxnm
    # Compute the resulting integer to ensure it's within reasonable size
    exp_a = 2 ** (maxnm - n)
    exp_b = 2 ** (maxnm - m)
    # Avoid degenerate tiny exponents simultaneously producing overly small answers
    if exp_a == 1 and exp_b == 1:
        continue
    ans = (a ** exp_a) * (b ** exp_b)
    # Keep answer within a reasonable range (up to about 10^20)
    if ans.bit_length() > 70:  # ~1.2e21 upper bound
        continue
    return {"a": a, "b": b, "n": n, "m": m, "power": power}

    def verifier(assign):
# Validate presence and types
for key in ("a", "b", "n", "m", "power"):
    if key not in assign:
        # missing parameter
        return (False, None)  # Missing assignment key
    if not isinstance(assign[key], int):
        return (False, None)  # Non-integer parameter supplied
a = assign["a"]; b = assign["b"]; n = assign["n"]; m = assign["m"]; power = assign["power"]
# Domain checks to ensure nontrivial radicals and exponent
if a <= 1 or b <= 1:
    return (False, None)  # Bases must exceed 1 to define principal real roots > 1
if n < 2 or m < 2:
    return (False, None)  # Enforce deeper-than-trivial telescoping
# Enforce the intended clearing exponent to prevent trivial shortcuts
maxnm = max(n, m)
intended_power = 2 ** maxnm
if power != intended_power:
    return (False, None)  # Provided power does not match 2^{max(n,m)}
# Compute the answer using the telescoping identity:
# For any a>1 and integer r>=1, (a-1)/prod_{k=1..r}(a^{1/2^k}+1) = a^{1/2^r} - 1.
# Hence letting u = a^{1/2^n} - 1 and v = b^{1/2^m} - 1,
# the given x equals uv and y equals u + v, so x + y + 1 = (u+1)(v+1) = a^{1/2^n} b^{1/2^m}.
# Therefore (x+y+1)^{2^{max(n,m)}} = a^{2^{max(n,m)-n}} b^{2^{max(n,m)-m}}.
exp_a = 2 ** (maxnm - n)
exp_b = 2 ** (maxnm - m)
answer = (a ** exp_a) * (b ** exp_b)
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")
